//! CG-5: the pre-registered answer, the three arms against each other, the
//! mutants, and the refusals. Fixtures are regenerated by
//! `.claude/probes/2026-11-11-cg5-defuse/regenerate.sh`.

use cg_defuse_probe::{
    Class, DeriveRefusal, Facts, FactsRefusal, Site, derive, fixpoint, nesting_class, parse,
    source_class,
};

const FUEL: usize = 64;

fn rows(name: &str) -> Facts {
    let path = format!(
        "{}/tests/data/{name}.defuse.tsv",
        env!("CARGO_MANIFEST_DIR")
    );
    parse(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// `(file, line, class)` of every site outside `fixture.rs`, duplicates
/// (one source statement copied by Charon) folded when they agree.
fn table(facts: &Facts) -> Vec<(String, u32, Class)> {
    let d = derive(facts, FUEL).unwrap();
    let mut out: Vec<(String, u32, Class)> = d
        .verdicts
        .iter()
        .filter(|v| v.site.file != "src/fixture.rs")
        .map(|v| (v.site.file.clone(), v.site.line, v.class))
        .collect();
    out.sort();
    out.dedup();
    out
}

fn row(file: &str, line: u32, class: Class) -> (String, u32, Class) {
    (file.to_string(), line, class)
}

/// Fixed on EXO-237 before any derivation existed.
fn preregistered() -> Vec<(String, u32, Class)> {
    vec![
        row("src/arm_a.rs", 75, Class::PerElement),
        row("src/arm_b.rs", 245, Class::ScalarThreshold),
        row("src/method.rs", 58, Class::ScalarThreshold),
        row("src/oracle.rs", 62, Class::PerElement),
    ]
}

#[test]
fn the_derivation_gives_the_preregistered_answer() {
    assert_eq!(table(&rows("m0")), preregistered());
}

#[test]
fn every_classified_site_carries_a_proof_and_unknown_carries_none() {
    let d = derive(&rows("m0"), FUEL).unwrap();
    assert_eq!(d.verdicts.len(), 16);
    let mut unknown = 0;
    for v in &d.verdicts {
        match v.class {
            Class::Unknown => {
                unknown += 1;
                assert!(v.proof.is_none());
            }
            _ => assert!(
                v.proof.as_ref().is_some_and(|p| !p.is_empty()),
                "{:?}",
                v.site
            ),
        }
    }
    // The three remainders in `fixture.rs` whose divisor is a global place.
    assert_eq!(unknown, 3);
}

#[test]
fn egglog_and_the_plain_fixpoint_agree_on_every_site_of_every_fixture() {
    let mut sites = 0;
    for name in ["m0", "m1", "m2", "m3"] {
        let facts = rows(name);
        let derived: Vec<Class> = derive(&facts, FUEL)
            .unwrap()
            .verdicts
            .iter()
            .map(|v| v.class)
            .collect();
        assert_eq!(derived, fixpoint(&facts), "{name}");
        sites += derived.len();
    }
    assert_eq!(sites, 16 + 16 + 15 + 16);
}

#[test]
fn the_source_scan_agrees_on_the_four_sites_without_reading_any_row() {
    let lab = format!("{}/../foundry-parity-lab", env!("CARGO_MANIFEST_DIR"));
    for (file, line, class) in preregistered() {
        let text = std::fs::read_to_string(format!("{lab}/{file}")).unwrap();
        assert_eq!(
            source_class(&text, line as usize),
            Some(class),
            "{file}:{line}; if the line moved, regenerate the fixtures"
        );
    }
}

fn mutant_source(name: &str) -> String {
    let path = format!(
        "{}/tests/data/src-{name}/method.rs",
        env!("CARGO_MANIFEST_DIR")
    );
    std::fs::read_to_string(path).unwrap()
}

fn method_sites(facts: &Facts) -> Vec<Site> {
    facts
        .sites
        .iter()
        .filter(|s| s.file == "src/method.rs")
        .cloned()
        .collect()
}

/// Mutant 1: the division moves into the loop and divides by the element.
#[test]
fn a_division_by_the_loop_element_flips_to_per_element_in_every_arm() {
    let facts = rows("m1");
    let mut expected = preregistered();
    expected[2] = row("src/method.rs", 57, Class::PerElement);
    assert_eq!(table(&facts), expected);
    assert_eq!(
        source_class(&mutant_source("m1"), 57),
        Some(Class::PerElement)
    );
}

/// Mutant 2: the division is gone; so is the row, and nothing else moves.
#[test]
fn removing_the_division_removes_the_site() {
    let facts = rows("m2");
    assert!(method_sites(&facts).is_empty());
    let mut expected = preregistered();
    expected.remove(2);
    assert_eq!(table(&facts), expected);
    assert_eq!(rows("m0").sites.len() - facts.sites.len(), 1);
    assert_eq!(source_class(&mutant_source("m2"), 58), None);
}

/// Mutant 3: the division moves into the loop with the same operands. The
/// def-use arms keep it scalar; loop nesting calls it per-element.
#[test]
fn a_scalar_division_inside_the_loop_stays_scalar_where_nesting_gets_it_wrong() {
    let facts = rows("m3");
    let mut expected = preregistered();
    expected[2] = row("src/method.rs", 57, Class::ScalarThreshold);
    assert_eq!(table(&facts), expected);
    assert_eq!(
        source_class(&mutant_source("m3"), 57),
        Some(Class::ScalarThreshold)
    );
    let site = &method_sites(&facts)[0];
    assert_eq!(site.loop_depth, 1);
    assert_eq!(nesting_class(site), Class::PerElement);
}

/// On the unmutated crate nesting is already wrong once: Charon copies the
/// tail of `cook_ops` into the loop's exit paths.
#[test]
fn loop_nesting_misclassifies_one_of_the_four_real_sites() {
    let facts = rows("m0");
    let wrong: Vec<(String, u32)> = facts
        .sites
        .iter()
        .filter(|s| s.file != "src/fixture.rs")
        .filter(|s| {
            let want = preregistered()
                .into_iter()
                .find(|(f, l, _)| *f == s.file && *l == s.line)
                .unwrap()
                .2;
            nesting_class(s) != want
        })
        .map(|s| (s.file.clone(), s.line))
        .collect();
    assert_eq!(
        wrong,
        vec![
            ("src/arm_b.rs".to_string(), 245),
            ("src/arm_b.rs".to_string(), 245)
        ]
    );
}

const HEAD: &str = "#version 1\n#schema kind\tfn\tfields\n";

fn synthetic(body: &str) -> Facts {
    parse(&format!("{HEAD}{body}")).unwrap()
}

#[test]
fn a_local_with_two_different_definitions_is_not_scalar() {
    let one =
        "ARG\tf\t1\ta\nDEF\tf\t2\t1\tassign\t3\t0\t1\nSITE\tf\t9\tDiv\tx.rs\t5\t0\t2\tconst\n";
    assert_eq!(fixpoint(&synthetic(one)), vec![Class::ScalarThreshold]);
    let two = format!("{one}DEF\tf\t2\t4\tassign\t4\t1\t1\n");
    let facts = synthetic(&two);
    assert_eq!(fixpoint(&facts), vec![Class::Unknown]);
    let d = derive(&facts, FUEL).unwrap();
    assert_eq!(d.verdicts[0].class, Class::Unknown);
    assert!(d.verdicts[0].proof.is_none());
}

#[test]
fn a_statement_copied_by_charon_is_one_definition() {
    let body = "ARG\tf\t1\ta\nDEF\tf\t2\t1\tassign\t3\t0\t1\nDEF\tf\t2\t7\tassign\t3\t1\t1\n\
                SITE\tf\t9\tDiv\tx.rs\t5\t0\t2\tconst\n";
    let facts = synthetic(body);
    assert_eq!(facts.defs[&("f".to_string(), 2)].len(), 1);
    assert_eq!(
        derive(&facts, FUEL).unwrap().verdicts[0].class,
        Class::ScalarThreshold
    );
}

#[test]
fn dependence_on_an_element_is_followed_through_a_chain() {
    let body = "ARG\tf\t1\ta\nDEF\tf\t2\t1\tcall\t3\t1\t1\nELEM\tf\t2\t1\tnext\n\
                DEF\tf\t3\t2\tassign\t4\t1\t2\nDEF\tf\t4\t3\tassign\t5\t1\t3\n\
                SITE\tf\t9\tDiv\tx.rs\t6\t0\t1\t4\nSITE\tf\t10\tDiv\tx.rs\t7\t0\t1\t1\n";
    let facts = synthetic(body);
    let d = derive(&facts, FUEL).unwrap();
    assert_eq!(d.verdicts[0].class, Class::PerElement);
    assert_eq!(d.verdicts[1].class, Class::ScalarThreshold);
    assert_eq!(
        fixpoint(&facts),
        vec![Class::PerElement, Class::ScalarThreshold]
    );
}

#[test]
fn a_site_that_would_be_both_is_refused() {
    let body = "ARG\tf\t1\ta\nELEM\tf\t1\t1\tnext\nSITE\tf\t9\tDiv\tx.rs\t6\t0\t1\tconst\n";
    assert_eq!(
        derive(&synthetic(body), FUEL).unwrap_err(),
        DeriveRefusal::Conflict
    );
}

#[test]
fn running_out_of_fuel_is_a_refusal_not_a_partial_answer() {
    assert_eq!(derive(&rows("m0"), 1).unwrap_err(), DeriveRefusal::Fuel(1));
}

#[test]
fn malformed_rows_are_refused() {
    assert_eq!(parse("ARG\tf\t1\ta\n").unwrap_err(), FactsRefusal::Version);
    assert_eq!(
        parse(&format!("{HEAD}NOPE\tf\t1\n")).unwrap_err(),
        FactsRefusal::Row(3)
    );
    assert_eq!(
        parse(&format!("{HEAD}SITE\tf\t9\tDiv\n")).unwrap_err(),
        FactsRefusal::Row(3)
    );
    assert_eq!(
        parse(&format!("{HEAD}ARG\tf\tx\ta\n")).unwrap_err(),
        FactsRefusal::Number(3)
    );
}

#[test]
fn a_value_read_through_an_index_is_an_element_source() {
    let body = "ARG\tf\t1\ta\nDEF\tf\t2\t1\tassign\t3\t0\t1\nINDEX\tf\t2\t1\n\
                SITE\tf\t9\tDiv\tx.rs\t6\t0\t2\tconst\n";
    let facts = synthetic(body);
    assert_eq!(
        derive(&facts, FUEL).unwrap().verdicts[0].class,
        Class::PerElement
    );
    assert_eq!(fixpoint(&facts), vec![Class::PerElement]);
}

#[test]
fn the_source_scan_ignores_a_loop_that_has_closed() {
    let src = "fn f(q: i32, xs: &[i32]) -> i32 {\n    let mut y = 0;\n    for d in xs {\n        \
               y += d;\n    }\n    let d = 4;\n    y + q / d\n}\n";
    assert_eq!(source_class(src, 7), Some(Class::ScalarThreshold));
    let inside = "fn f(q: i32, xs: &[i32]) -> i32 {\n    let mut y = 0;\n    for d in xs {\n        \
                  y += q / d;\n    }\n    y\n}\n";
    assert_eq!(source_class(inside, 4), Some(Class::PerElement));
}

#[test]
fn the_source_scan_treats_an_indexed_read_as_per_element() {
    let src = "fn f(q: i32, xs: &[i32], i: usize) -> i32 {\n    xs[i] / q\n}\n";
    assert_eq!(source_class(src, 2), Some(Class::PerElement));
    let plain = "fn f(q: i32, x: i32) -> i32 {\n    x / q // not xs[i]\n}\n";
    assert_eq!(source_class(plain, 2), Some(Class::ScalarThreshold));
}
